WITH car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm,a.id_imovel,a.area FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_municipio='2929701' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2019 AND 2024 AND id_car IS NOT NULL AND TRIM(id_car)!=''),n AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem,COUNT(*) n_imoveis FROM p GROUP BY 1,2,3),b AS (SELECT c.id_imovel,op.id_referencia_bacen,op.valor_parcela_credito/n.n_imoveis credito,i.nome instituicao FROM p JOIN n USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) JOIN car c USING(id_car_norm) JOIN `basedosdados.br_bcb_sicor.instituicao_financeira` i ON i.cnpj_basico=op.cnpj_basico_instituicao_financeira WHERE c.area<0.1 AND i.nome='BCO DO NORDESTE DO BRASIL S.A.'),g AS (SELECT id_imovel,COUNT(DISTINCT id_referencia_bacen) operacoes,SUM(credito) credito FROM b GROUP BY 1) SELECT COUNT(*) micro_cars_bnb,MAX(operacoes) max_operacoes_outro_car,MAX(credito) max_credito_outro_car,COUNTIF(id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048') focal_present FROM g